def canIWin(maxChoosableInteger: int, desiredTotal: int) -> bool:
    if desiredTotal <= 0: return True
    total_sum = (maxChoosableInteger * (maxChoosableInteger + 1)) // 2
    if total_sum < desiredTotal: return False
    if total_sum == desiredTotal: return maxChoosableInteger % 2 == 1
    memo = {}
    def dp(mask, remaining):
        if mask in memo: return memo[mask]
        for i in range(1, maxChoosableInteger + 1):
            bit = 1 << i
            if not (mask & bit):
                if i >= remaining or not dp(mask | bit, remaining - i):
                    memo[mask] = True
                    return True
        memo[mask] = False
        return False
    return dp(0, desiredTotal)

